
const prompts=['What did you notice before deciding what it means?','Whose perspective is missing from this story?','What repair is yours to offer—and yours to decline?','Where is the visible exit from this commitment?','What note would help you return after an interruption?'];let promptIndex=0;document.querySelector('#next-prompt').onclick=()=>{promptIndex=(promptIndex+1)%prompts.length;document.querySelector('#practice-prompt').textContent=prompts[promptIndex]};
function download(name,text,type='text/plain'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function intro(){return 'PIXIE / CREATIVE EXPERIENCE DECKS — collaborator introduction\n\nRole: '+document.querySelector('#role').value+'\nSpecialty: '+document.querySelector('#specialty').value+'\nPortfolio (optional): '+document.querySelector('#portfolio').value+'\n\n'+document.querySelector('#intro').value+'\n\nI would like to discuss scope, availability, compensation, credit and rights before accepting an assignment.\nPrepared locally; not submitted. Training pathway: https://loptrlab.com/training\n'}
document.querySelector('#download-intro').onclick=()=>{download('PIXIE-collaborator-introduction.txt',intro());document.querySelector('#draft-status').textContent='Your introduction has been prepared as a download. Nothing was submitted.'};document.querySelector('#copy-intro').onclick=async()=>{try{await navigator.clipboard.writeText(intro());document.querySelector('#draft-status').textContent='Introduction copied. Nothing was submitted.'}catch{document.querySelector('#draft-status').textContent='Copy is unavailable in this preview. Use Download introduction instead.'}};
const ids=['price','sets','landed','box','art','setup','buffer','variable','fee','flat'];const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(x);let scenario;
function recalc(){let a=Object.fromEntries(ids.map(id=>[id,Number(document.getElementById(id).value)]));if(Object.values(a).some(x=>!Number.isFinite(x)||x<0)||a.sets<1||a.fee>100){document.getElementById('break-even').textContent='Check inputs';return}a.sets=Math.floor(a.sets);let available=Math.max(0,a.sets-10),fixed=a.sets*(a.landed+a.box)+a.art+a.setup+a.buffer,c=a.price*(1-a.fee/100)-a.flat-a.variable,n=c>0?Math.ceil(fixed/c):null,s=available*c-fixed;scenario={...a,reserved_sets:Math.min(10,a.sets),sellable_sets:available,fixed_commitment:fixed,contribution:c,break_even_orders:n,surplus_at_sellout:s,status:'illustrative assumptions, not quotes',omissions:'owner labor, marketing, rights costs, returns and taxes unless separately included'};document.getElementById('break-even').textContent=n===null?'No positive margin':n+' orders';document.getElementById('sellable').textContent=available+' sets';document.getElementById('commitment').textContent=money(fixed);document.getElementById('contribution').textContent=money(c);document.getElementById('surplus').textContent=money(s);document.getElementById('viability').textContent=n===null?'The delivered price does not cover per-order costs.':n>available?'This scenario cannot break even within the available sets. Revisit price, costs or run size.':n===available?'Break-even requires every available set. There is no unsold-stock cushion.':'Break-even leaves '+(available-n)+' available sets. Test demand and replace assumptions with quotes.'}ids.forEach(id=>document.getElementById(id).addEventListener('input',recalc));document.getElementById('save-budget').onclick=()=>download('PIXIE-two-deck-cost-scenario.json',JSON.stringify(scenario,null,2),'application/json');recalc();
